    space_count = 0
    for char in text:
        if char == ' ':
            space_count += 1
        else:
            if space_count > 2:
                result.append('-' * space_count)
            elif space_count > 0:
                result.append('_' * space_count)
            space_count = 0
            result.append(char)
    if space_count > 2:
